  var nomorClean = sanitizeName(data.nomorRegister || data.nomorPengajuan || ("Sengketa_" + Date.now())).replace(/\\s+/g, "_");

  var kategoriFolder = payload.kategoriFolder || "03_Sengketa_Pemilu";
  var partyFolderName = payload.partyFolderName || ("Pemohon - " + namaPemohon);
  var caseFolderName = payload.caseFolderName || (pihakTermohon ? (nomorClean + " - Termohon " + pihakTermohon) : nomorClean);

  var folderUrl = "";
  var folderId = "";
